    [499] = { label = 'Stepping into an Ambuscade', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Procure information about Ambuscade by speaking with Gorpa-Masorpa in Mhaura (G-9).\n\nSpecial reward: Ambuscade Primer Volume 2', goal = 1, rewards = { sparks = 100, exp = 300 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0x104 },
