    [502] = { label = 'Mog House Exit: Windurst', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Speak to Ojha Rhawash in Windurst Walls (C-13), complete the quest "Flower Child," and expand the number of destinations to which you may travel from your Mog House.', goal = 1, rewards = { sparks = 100, exp = 300 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0x104 },
    [503] = { label = 'Mog House Exit: Jeuno', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Speak to Zona Shodhun in Port Jeuno (E-8), complete the quest "Pretty Little Things," and expand the number of destinations to which you may travel from your Mog House.', goal = 1, rewards = { sparks = 100, exp = 300 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0xFC },
    [504] = { label = 'Mog House Exit: Aht Urhgan', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Speak to Ahkk Jharcham in Aht Urhgan Whitegate (I-10), complete the quest "Keeping Notes," and expand the number of destinations to which you may travel from your Mog House.', goal = 1, rewards = { sparks = 100, exp = 300 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0x104 },
    [505] = { label = 'Obtain a Support Job', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Speak to Isacio in Selbina (G-10) and complete the quest "Elder Memories" or speak to Vera in Mhaura (G-10) and complete the quest "The Old Lady" to obtain a support job.\nRequirement: Be level 18 or higher.', goal = 1, rewards = { sparks = 100, exp = 500 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0xFC },
    [506] = { label = 'Obtain an Alter Ego: San d\'Oria', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Speak to Gondebaud in Southern San d\'Oria (L-6), complete the quest "Trust: San d\'Oria," and obtain an alter ego of Excenmille.\nRequirement: Be level 5 or higher.', goal = 1, rewards = { sparks = 100, exp = 500 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0x10C },
    [507] = { label = 'Obtain an Alter Ego: Bastok', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Speak to Clarion Star in Port Bastok (K-7), complete the quest "Trust: Bastok," and obtain an alter ego of Naji.\nRequirement: Be level 5 or higher.', goal = 1, rewards = { sparks = 100, exp = 500 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0x104 },
    [508] = { label = 'Obtain an Alter Ego: Windurst', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Speak to Wetata in Windurst Woods (G-10), complete the quest "Trust: Windurst," and obtain an alter ego of Kupipi.\nRequirement: Be level 5 or higher.', goal = 1, rewards = { sparks = 100, exp = 500 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0x10C },
    [509] = { label = 'Obtain a Chocobo License', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Speak to Brutus in Upper Jeuno (G-7), complete the quest "Chocobo\'s Wounds," and obtain a chocobo license.\nRequirement: Be level 20 or higher.', goal = 1, rewards = { sparks = 100, exp = 600 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0x104 },
    [510] = { label = 'Obtain Job: Paladin', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Speak to Balasiel in Southern San d\'Oria (F-7), complete the quest line that begins with "A Squire\'s Test," and obtain the paladin job.\nRequirements: Be level 30 or higher, reputation of "I mighta hearda somebody that went by that name" or the like.', goal = 1, rewards = { sparks = 100, exp = 300 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0xF4 },
    [511] = { label = 'Obtain Job: Dark Knight', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Speak to Gumbah in Bastok Mines (J-7), complete the quest "Blade of Darkness," and obtain the dark knight job.\nRequirement: Be level 30 or higher.', goal = 1, rewards = { sparks = 100, exp = 300 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0xFC },
    [512] = { label = 'Obtain Job: Beastmaster', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Examine the Door: Merchant\'s House in Upper Jeuno (G-11), complete the quest line that begins with "Save My Son," and obtain the beastmaster job.\nRequirements: Be level 30 or higher, Completion of "Chocobo\'s Wounds."', goal = 1, rewards = { sparks = 100, exp = 300 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0xFC },
    [513] = { label = 'Obtain Job: Bard', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Speak to Mertaire in Lower Jeuno (I-8), complete the quest line that begins with "The Old Monument," and obtain the bard job.\nRequirement: Be level 30 or higher.', goal = 1, rewards = { sparks = 100, exp = 300 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0xF4 },
