    [516] = { label = 'Obtain Job: Ninja', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Speak to Kaede in Port Bastok (J-5), complete the quest "Ayame and Kaede," and obtain the ninja job.\nRequirements: Be level 30 or higher, installation of Rise of the Zilart.', goal = 1, rewards = { sparks = 100, exp = 300 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0xF4 },
    [517] = { label = 'Obtain Job: Dragoon', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Speak to either Arminibit or Ceraulian in Port San d\'Oria (I-10), complete the quest "The Holy Crest," and obtain the dragoon job.\nRequirements: Be level 30 or higher, installation of Rise of the Zilart.', goal = 1, rewards = { sparks = 100, exp = 300 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', not_repeatable = true, repeat_source = 'lsb:scripts/globals/roe_records.lua flags', title_offset = 0x70, description_offset = 0xF4 },
