    [3063] = { label = 'Tiger\'s Teeth (VBD)', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Complete the quest Tiger\'s Teeth the requisite number of times. Goal: Deliver 3 black tiger fangs to Taumila in Southern San d\'Oria (F-9).\nSpecial Reward: 30 plaudits.', goal = 1, rewards = { sparks = 500, exp = 2500 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', title_offset = 0x70, description_offset = 0xF4 },
