    [3075] = { label = 'Jingly (VBD)', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Play Mandragora Mania by speaking with\nthe Mandragora Assistant in various\nareas and receive the requisite amount\nof jingly.  Playable Locations (Mandragora\nAssistant): Southern San d\'Oria (K-10),\nBastok Mines (I-9), Ru\'Lude Gardens (G-9),', goal = 1, rewards = { sparks = 500, exp = 2500 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', title_offset = 0x70, description_offset = 0xEC },
    [3079] = { label = 'Auctioning (VBD)', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'List a phoenix feather, malboro fiber, black beetle blood, damascene cloth, or oxblood on the auction house the requisite number of times.\nSpecial Reward: 30 plaudits.', goal = 1, rewards = { sparks = 500, exp = 2500 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', title_offset = 0x70, description_offset = 0xF4 },
