    [3095] = { label = 'Donations (VBD)', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Donate funds to Gajaad in Al Zahbi \n(J-6) the requisite number of times.\nSpecial Reward: 30 plaudits.', goal = 1, rewards = { sparks = 500, exp = 2500 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', title_offset = 0x70, description_offset = 0xEC },
    [3096] = { label = 'Gobbie Mystery Box (VBD)', source = 'dat:ROM/307/16.DAT rotate-right-5', description = 'Open the Gobbie Mystery Box the requisite number of times.\nGoblin Mystery Box Locations and NPCs:\nSouthern San d\'Oria (L-7) Mystrix\nPort San d\'Oria (I-10) Habitox\nBastok Mines (K-9) Bountibox\nBastok Markets (I-7) Specilox\nWindurst Walls (C-14) Arbitrix', goal = 1, rewards = { sparks = 500, exp = 2500 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', title_offset = 0x70, description_offset = 0x104 },
