    [3360] = { label = 'Mythril Marathon (W)', source = 'dat:ROM/307/16.DAT rotate-right-5', description = '(Weekly) Insert mine gravel into the special device in Palborough Mines and receive mythril sand the requisite number of times.', goal = 10, rewards = { sparks = 50, exp = 1115 }, reward_source = 'dat:ROM/307/16.DAT fixed-fields', title_offset = 0x70, description_offset = 0xFC },
